cat >> styles.css <<'EOF'
/* Responsive navigation: scrollable sidebar, top-right trigger, tap-away scrim. */
.sidebar{overflow-y:auto;overflow-x:hidden;overscroll-behavior:contain;scrollbar-width:thin;scrollbar-color:#d8dfec transparent;-webkit-overflow-scrolling:touch}
.sidebar::-webkit-scrollbar{width:6px}
.sidebar::-webkit-scrollbar-track{background:transparent}
.sidebar::-webkit-scrollbar-thumb{background:#d8dfec;border-radius:999px}
.sidebar::-webkit-scrollbar-thumb:hover{background:#c2cce0}
.sidebar-close{display:none}
.sidebar-scrim{display:none}
@media(max-width:1050px){.topbar-actions{gap:14px}}
@media(max-width:700px){
  .topbar-actions{gap:8px}
  .breadcrumb{margin-left:0;margin-right:auto;min-width:0;overflow:hidden}
  .breadcrumb strong{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
  .mobile-menu{display:grid;gap:5px;width:36px;height:36px;place-content:center;background:#fff;border:1px solid #e9edf4;border-radius:11px;cursor:pointer;transition:background .2s,border-color .2s,transform .2s}
  .mobile-menu:hover{background:#f3f5ff;border-color:#d5dcf5}
  .mobile-menu:focus-visible{outline:3px solid #9caaf3;outline-offset:2px}
  .mobile-menu span{display:block;width:15px;height:1.8px;border-radius:2px;background:#71809a;transition:transform .22s ease,opacity .2s ease,background .2s}
  .mobile-menu[aria-expanded="true"]{background:#edf0ff;border-color:#c9d2f2}
  .mobile-menu[aria-expanded="true"] span:first-child{transform:translateY(3.4px) rotate(45deg)}
  .mobile-menu[aria-expanded="true"] span:last-child{transform:translateY(-3.4px) rotate(-45deg)}
  .sidebar{width:min(84vw,304px);max-height:100dvh;padding:22px 16px calc(18px + env(safe-area-inset-bottom));z-index:12;visibility:hidden;transition:transform .3s cubic-bezier(.22,.8,.3,1),visibility .3s;box-shadow:18px 0 48px rgba(28,40,68,.16);overscroll-behavior:contain}
  .sidebar.open{visibility:visible;transform:translateX(0)}
  .sidebar-close{display:grid;place-items:center;position:absolute;top:16px;right:12px;width:34px;height:34px;border:1px solid #e6eaf2;border-radius:10px;background:rgba(255,255,255,.86);color:#7f8ba0;font:500 20px/1 'DM Sans',sans-serif;cursor:pointer;z-index:2;transition:background .18s,color .18s,border-color .18s}
  .sidebar-close:hover{background:#f1f3fb;color:#5b6fd1;border-color:#d4daf0}
  .sidebar-close:focus-visible{outline:3px solid #9caaf3;outline-offset:2px}
  .sidebar-scrim{display:block;position:fixed;inset:0;z-index:11;background:rgba(16,25,43,.42);backdrop-filter:blur(2px);-webkit-backdrop-filter:blur(2px);opacity:0;visibility:hidden;pointer-events:none;transition:opacity .26s ease,visibility .26s}
  .sidebar-scrim.open{opacity:1;visibility:visible;pointer-events:auto}
  body.sidebar-open{overflow:hidden}
  body.sidebar-open .mobile-menu{position:relative;z-index:13}
}
@media(max-width:360px){
  .topbar{padding:0 12px}
  .topbar-actions{gap:6px}
  .breadcrumb{font-size:11px}
  .breadcrumb span:first-child,.crumb-slash{display:none}
  .mobile-menu,.theme-toggle{width:34px;height:34px}
}
body[data-theme="dark"] .sidebar{scrollbar-color:#46506a transparent}
body[data-theme="dark"] .sidebar::-webkit-scrollbar-thumb{background:#46506a}
body[data-theme="dark"] .sidebar-close{background:#2a3145;border-color:#3c4459;color:#b4bfd4}
body[data-theme="dark"] .sidebar-close:hover{background:#353d55;border-color:#59668c;color:#d5dcff}
body[data-theme="dark"] .sidebar-scrim{background:rgba(5,9,17,.62)}
body[data-theme="dark"] .mobile-menu:hover{background:#2b3246;border-color:#414a63}
body[data-theme="dark"] .mobile-menu[aria-expanded="true"]{background:#333b57;border-color:#59668c}
EOF
