313: @keyframes write-block{0%,8%{clip-path:inset(0 100% 0 0)}32%,76%{clip-path:inset(0 0 0 0)}92%,100%{clip-path:inset(0 100% 0 0)}}
314: @keyframes write-line{0%,12%{transform:scaleX(0);opacity:.35}34%,76%{transform:scaleX(1);opacity:1}92%,100%{transform:scaleX(0);opacity:.35}}
315: @keyframes ink-stamp{0%,38%{opacity:.3;scale:.7}52%,78%{opacity:1;scale:1}94%,100%{opacity:.3;scale:.7}}
316: @keyframes art-glow-breathe{from{opacity:.58;scale:.94}to{opacity:.84;scale:1.04}}
317: @keyframes sparkle-drift{0%,100%{translate:0 0;rotate:0deg;opacity:.65}50%{translate:0 -6px;rotate:12deg;opacity:1}}
318: @keyframes orbit-shimmer{from{opacity:.48}to{opacity:.9}}
319: @keyframes orb-drift{0%,100%{translate:0 0;scale:1}50%{translate:-10px -8px;scale:1.14}}
320: @media(prefers-reduced-motion:reduce){.hero-art *{animation:none!important}}

