import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, process.platform === 'darwin' ? 'metal.json' : 'linux.json'), 'utf8'))
const browser = await chromium.launch(config.browser.launchOptions)
try {
  const page = await browser.newPage({ viewport: { width: 390, height: 844 }, reducedMotion: 'reduce' })
  const errors = []
  page.on('pageerror', e => errors.push(e.message))
  await page.goto('http://127.0.0.1:8765', { waitUntil: 'load' })
  const sidebar = page.locator('#sidebar')
  const menu = page.locator('#mobileMenu')
  const scrim = page.locator('#sidebarScrim')
  const sidebarOverflow = await sidebar.evaluate(el => getComputedStyle(el.querySelector('.sidebar-scroll')).overflowY)
  if (sidebarOverflow !== 'auto') throw new Error(`Expected mobile sidebar scrolling; got ${sidebarOverflow}`)
  await menu.click()
  if (await menu.getAttribute('aria-expanded') !== 'true' || !(await sidebar.evaluate(el => el.classList.contains('open')))) throw new Error('Mobile menu did not open')
  await scrim.click({ position: { x: 370, y: 400 } })
  if (await menu.getAttribute('aria-expanded') !== 'false') throw new Error('Backdrop did not dismiss sidebar')
  await menu.click()
  await page.keyboard.press('Escape')
  if (await menu.getAttribute('aria-expanded') !== 'false') throw new Error('Escape did not dismiss sidebar')
  const animation = await page.locator('.page-front').evaluate(el => getComputedStyle(el).animationName)
  if (animation !== 'none') throw new Error(`Reduced motion not respected; animation is ${animation}`)
  await page.locator('#themeToggle').click()
  if (await page.locator('body').getAttribute('data-theme') !== 'dark') throw new Error('Dark theme toggle failed')
  await page.setViewportSize({ width: 1440, height: 900 })
  const overflow = await page.evaluate(() => document.documentElement.scrollWidth > document.documentElement.clientWidth)
  if (overflow) throw new Error('Unexpected horizontal overflow at desktop width')
  if (errors.length) throw new Error(`Browser errors: ${errors.join('; ')}`)
  console.log('Browser checks passed: mobile scroll/dismiss, Escape, reduced motion, dark theme, desktop overflow, no page errors.')
} finally { await browser.close() }

