.editor-toolbar{display:flex;flex-wrap:wrap;gap:8px;align-items:center;padding:9px 10px;border:1px solid var(--line);border-radius:12px;background:#fff}
body[data-theme="dark"] .editor-toolbar{background:#252c3f;border-color:#3a4258}
.editor-tools{display:flex;gap:6px}
.editor-btn{border:1px solid #e3e8f2;background:#fff;color:var(--ink);font:600 10.5px 'DM Sans',sans-serif;padding:8px 12px;border-radius:9px;cursor:pointer;transition:background .2s,border-color .2s,color .2s}
.editor-btn:hover{background:#f3f5ff;border-color:#d5dcf5}
.editor-btn.active{background:#e8edff;border-color:#c3cffa;color:#4a5df0}
.editor-btn.ghost{background:none}
.editor-btn.ghost:hover{background:#fdf1ef;border-color:#f2cfc8;color:#c25343}
body[data-theme="dark"] .editor-btn{background:#2c344a;border-color:#414a63;color:#e6eaf6}
body[data-theme="dark"] .editor-btn:hover{background:#333c57}
body[data-theme="dark"] .editor-btn.active{background:#3a466f;border-color:#5d6ea6;color:#cdd8ff}
.editor-field{display:flex;align-items:center;gap:6px;font:500 10.5px 'DM Sans',sans-serif;color:var(--muted)}
.editor-field input[type="color"]{width:28px;height:28px;padding:2px;border:1px solid #e3e8f2;border-radius:7px;background:none;cursor:pointer}
body[data-theme="dark"] .editor-field input[type="color"]{border-color:#414a63}
.editor-field select{font:600 10.5px 'DM Sans',sans-serif;color:var(--ink);border:1px solid #e3e8f2;border-radius:7px;padding:5px;background:#fff}
body[data-theme="dark"] .editor-field select{background:#2c344a;border-color:#414a63;color:#e6eaf6}
.editor-scroll{max-width:100%;overflow:auto;display:flex;justify-content:center}
.editor-stage{position:relative;line-height:0;border-radius:10px;box-shadow:0 8px 26px rgba(48,65,112,.14);overflow:hidden;touch-action:none;background:#fff}
.editor-stage canvas{display:block;max-width:100%;height:auto}
.editor-stage #editorInkCanvas{position:absolute;inset:0;width:100%;height:100%}
.editor-items{position:absolute;inset:0}
.editor-empty{position:absolute;inset:0;display:grid;place-items:center;background:#f4f6fb;color:var(--muted);font:500 11px 'DM Sans',sans-serif;line-height:1.5;text-align:center;padding:12px}
body[data-theme="dark"] .editor-empty{background:#20263a;color:#8b96b3}
.editor-item{position:absolute;transform:translate(-2px,-2px);cursor:grab;touch-action:none;user-select:none;-webkit-user-select:none}
.editor-item:active{cursor:grabbing}
.editor-item.is-text{white-space:pre}
.editor-item-text{outline:none;min-width:6px;display:inline-block;white-space:pre;line-height:1.25;caret-color:currentColor}
.editor-item.selected{outline:2px dashed #5676e8;outline-offset:3px;border-radius:2px}
.editor-item.is-image img{display:block;width:100%;height:auto;box-shadow:0 2px 10px rgba(20,30,60,.25)}
.editor-item-resize{position:absolute;right:-8px;bottom:-8px;width:15px;height:15px;border-radius:4px;background:#fff;border:1.5px solid #5676e8;cursor:nwse-resize;touch-action:none}
.editor-footer{display:flex;align-items:center;gap:10px;justify-content:center;flex-wrap:wrap}
.editor-page-label{font:600 10.5px 'DM Sans',sans-serif;color:var(--muted)}
.editor-hint{font:500 10px 'DM Sans',sans-serif;color:var(--muted);opacity:.9;flex-basis:100%;text-align:center}
@media(prefers-reduced-motion:reduce){.editor-btn,.editor-item{transition:none!important}}

