import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
const browser = await chromium.launch({ ...config.browser.launchOptions, headless: true })
try {
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } })
  const errors = []
  page.on('pageerror', e => errors.push(e.message))
  page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()) })
  await page.goto('http://127.0.0.1:8765', { waitUntil: 'load' })
  console.log('kartu alat:', await page.locator('#toolsGrid .tool-card').count())
  for (const id of ['ocr', 'protect', 'unlock', 'edit']) {
    await page.click(`[data-tool="${id}"]`)
    const title = (await page.textContent('#modalTitle')).trim()
    console.log(id, '→', title)
    await page.keyboard.press('Escape')
  }
  await page.screenshot({ path: '/tmp/opencode/paperly-capture/tools-grid.jpg', quality: 60, type: 'jpeg' })
  console.log(errors.length ? 'ERRORS:\n' + errors.join('\n') : 'tanpa error')
} finally { await browser.close() }

import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
const browser = await chromium.launch({ ...config.browser.launchOptions, headless: true })
try {
  const page = await (await browser.newContext({ viewport: { width: 1440, height: 900 } })).newPage()
  page.on('pageerror', e => console.error('pageerror:', e.message))
  page.on('console', m => { if (m.type() === 'error') console.error('console:', m.text()) })
  await page.goto('http://127.0.0.1:8765', { waitUntil: 'load' })
  await page.click('[data-tool="unlock"]')
  await page.setInputFiles('#fileInput', '/tmp/opencode/assets/enc-test.pdf')
  await page.fill('#unlockPassword', 'rahasia123')
  await page.click('#modalAction')
  await page.waitForTimeout(2000)
  console.log('error setelah sandi salah:', JSON.stringify(await page.locator('#modalError').textContent()))
  await page.fill('#unlockPassword', 'rahasia')
  const dl = page.waitForEvent('download', { timeout: 15000 }).then(d => { console.log('DOWNLOAD OK:', d.suggestedFilename()); return d })
  await page.click('#modalAction')
  await page.waitForTimeout(3000)
  console.log('error setelah sandi benar:', JSON.stringify(await page.locator('#modalError').textContent()))
  const r = await Promise.race([dl.catch(e => 'tanpa unduhan'), page.waitForTimeout(16000).then(() => 'timeout')])
  console.log('hasil:', typeof r === 'string' ? r : 'unduhan tersimpan')
} finally { await browser.close() }

