import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
const browser = await chromium.launch({ ...config.browser.launchOptions, headless: true })
try {
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 } })
  const page = await ctx.newPage()
  await page.goto('http://127.0.0.1:8765', { waitUntil: 'load' })
  await page.setViewportSize({ width: 390, height: 844 })
  await page.click('#mobileMenu')
  const info = await page.evaluate(() => {
    const s = document.getElementById('sidebarScrim')
    const cs = getComputedStyle(s)
    return { cls: s.className, pos: cs.position, vis: cs.visibility, pe: cs.pointerEvents, z: cs.zIndex, display: cs.display, opacity: cs.opacity, inset: cs.inset }
  })
  console.log('scrim:', JSON.stringify(info, null, 1))
  console.log('elementFromPoint:', await page.evaluate(() => { const el = document.elementFromPoint(370, 400); return (el.id || el.className) }))
